sys_transform_script.script:
//The onAfter event script is processed at the end of a row transformation, after the source row has been transformed into the target row and saved.
//https://docs.servicenow.com/bundle/xanadu-integrate-applications/page/script/server-scripting/reference/r_MapWithTransformationEventScripts.html
(function runTransformScript(source, map, log, target) {
    const posCode = source.u_position_code.toString();
    const timeStamp = new Date().toISOString(); //performance.timeOrigin + performance.now();
    const infoStr = 'OHS - ' + timeStamp + ' - Row: ' + source.sys_import_row +
        ' - onAfter - ';

    const actionTaken = source.u_action_s__taken_by_manager.toString().trim(); //some entries are " ", we need to remove them
    const timeLineStart = source.u_timelines____ntrol_measures.toString().trim(); //some entries are " ", we need to remove them
    const timeLineEnd = source.u_timelines____y__implemented
        .toString().trim(); //some entries are " ", we need to remove them
    const comments = source.u_comments.toString().trim(); //some entries are " ", we need to remove them

    //only return if there's an action
    if (posCode !== null && posCode !== '') { //checking posCode to not add unlinked records
        if (actionTaken !== null && actionTaken.length > 300) {
            target.setWorkflow(false); //doesn't work if left alone
            target['comments'] = 'Full description:\n\n' + actionTaken;
            target.update(); //should simply add a comment

            gs.debug(infoStr + 'action_taken added to comment' +
                '\n\nnumber: ' + target.number +
                '\nx_hccc_hoc_ohs_hira_action:' + target.getUniqueValue() +
                '\nx_hccc_hoc_ohs_hazard_investigation_and_risk_assessment:' + target.parent_hazard
            );
        }

        if (timeLineStart !== null && timeLineStart.length > 1) {
            target.setWorkflow(false); //doesn't work if left alone
            target['comments'] = 'Timelines - Start Date of Implementing Control Measures:\n\n' + timeLineStart;
            target.update(); //should simply add a comment
        }
        if (timeLineEnd !== null && timeLineEnd.length > 1) {
            target.setWorkflow(false); //doesn't work if left alone
            target['comments'] = 'Timelines - Date When Control Measures Are Fully Implemented:\n\n' + timeLineEnd;
            target.update(); //should simply add a comment
        }
        if (comments !== null && comments.length > 1) {
            target.setWorkflow(false); //doesn't work if left alone
            target['comments'] = 'Comments:\n\n' + comments;
            target.update(); //should simply add a comment
        }
    }

})(source, map, log, target);
